Ext.define('GridHTML.store.ListStore', {
    extend: 'Ext.Base',

    buildData: function(spec, data) {
        var me = this,
            response = data.queryCommandsResult.queryCommandResult[0].grid.grid,

            columnas = response.columns || [],
            filas = response.rows || [],
            fields = [],
            i,
            dataStore = [],
            dimension,
            notDimension,
            tempItem,
            item,

            titles = {};


        for ( i in columnas) {

            item = columnas[i]['@name'];
            fields.push(item);
            titles[item] = columnas[i]['@label'];

            if (columnas[i]['@member'] == 'true') {
                dimension = columnas[i]['@label'];
            } else {
                notDimension = columnas[i]['@label'];
            }

        }

        if (filas instanceof Array === false) {
            filas = [filas.row];
        }

        for (i in filas) {

            item = filas[i];
            tempItem = {};
            for (var k in fields) {
                tempItem[fields[k]] = item[fields[k]].Caption || item[fields[k]].FmtValue;
            }

            dataStore.push(tempItem);

        }

        me.store = Ext.create('Ext.data.JsonStore', {
            fields: fields,
            data: dataStore,
            dimension: dimension,
            nonDimension: notDimension,
            titles: titles
        });


        return me.store;


    }

});